```typescript
import { runScript } from '/app/sdk/runner';

await runScript(async ({ bot, sdk }) => {
  const end = Date.now() + 27*60*1000;
  const inv = () => sdk.getInventory();
  const bonesCount = () => inv().filter(i => /bones/i.test(i.name)).reduce((a,i)=>a+i.count,0);
  const buryAll = async () => {
    for (;;) {
      const b = inv().find(i => /bones/i.test(i.name));
      if (!b) break;
      await sdk.sendUseItem(b.slot, 1);
      await sdk.waitForTicks(1);
    }
  };
  while (Date.now() < end) {
    if (bonesCount() >= 20) { await buryAll(); continue; }
    const chicken = sdk.findNearbyNpc(/^chicken$/i);
    if (!chicken) { await bot.walkTo(3237, 3296, 2); continue; }
    await bot.attack(chicken, 8000);
    await bot.dismissBlockingUI();
    // pick up bones
    for (let tries=0; tries<3; tries++) {
      const gi = sdk.findGroundItem(/bones/i);
      if (!gi) break;
      await bot.pickupItem(gi);
    }
  }
  await buryAll();
}, { disconnectAfter: true });
```

