import { runScript } from '/app/sdk/runner';

const keep = /bronze pickaxe|hammer|bread|shrimps|coins/i;

runScript(async ({ bot, sdk }) => {
  async function dropJunk() {
    for (const item of sdk.getInventory()) {
      if (!keep.test(item.name)) {
        await sdk.sendDropItem(item.slot);
        await new Promise(r => setTimeout(r, 150));
      }
    }
  }

  async function mineOres() {
    while (true) {
      const inv = sdk.getInventory();
      if (inv.length >= 28) break;
      const copper = inv.filter(i => /copper ore/i.test(i.name)).reduce((a,i)=>a+i.count,0);
      const tin = inv.filter(i => /tin ore/i.test(i.name)).reduce((a,i)=>a+i.count,0);
      let target;
